          onKeyDown$={[
            preventScrollKeys,
            $((e: KeyboardEvent) => onHandleKey("left", e)),
          ]}
        />
        <button
          type="button"
          class="ruler-handle"
          style={{ left: `${100 - rightPct}%` }}
          title="Right margin — drag, or use the arrow keys"
          aria-label="Right margin"
          role="slider"
          aria-orientation="horizontal"
          aria-valuemin={MARGIN_RANGE.right.min}
          aria-valuemax={MARGIN_RANGE.right.max}
          aria-valuenow={Number(m.right.toFixed(2))}
          aria-valuetext={`Right margin ${m.right.toFixed(2)} rem`}
          onPointerDown$={(e, el) => onHandleDown("right", e, el)}
          onKeyDown$={[
            preventScrollKeys,
            $((e: KeyboardEvent) => onHandleKey("right", e)),
          ]}
        />

        {dragging.value && readout.value && (
          <span
            class="ruler-readout"
            style={{
              left:
                dragging.value === "left"
                  ? `${leftPct}%`
                  : `${100 - rightPct}%`,
            }}
          >
            {readout.value}
          </span>
        )}
      </div>
    </div>
  );
});
/**
 * The forecast line in the status bar, beside the word count.
 *
 *   on pace for ~900 today (700–1,100) · word target ~Nov 14 (Nov 8 – 25)
 *
 * It also keeps the pace ledger: every saved draft's word count is folded
 * into `writing-pace-ledger`, so the history exists whether or not the line
 * is showing. The line itself steps aside in Zen and whenever the flow
 * reading says a run is building — a pace figure is the last thing a writer
