 */
export const StampPress = component$<{ animated?: boolean }>((props) => {
  const toolReady = useSignal(false);

  return (
    <span
      class={[
        "ink-stamp",
        { "ink-stamp--pressing": props.animated && toolReady.value },
      ]}
