    );
  }

  return (
    <span class="inline-flex items-center">
      <button
        type="button"
        onClick$={props.onPlay$}
        class="tool-btn"
        title={props.playLabel ?? "Read aloud"}
        aria-label={props.playLabel ?? "Read aloud"}
      >
        <span aria-hidden="true">♪</span>{" "}
        <span class="compositor-tool-label">read</span>
      </button>
    </span>
  );
});
import { $, component$, useStore, useVisibleTask$ } from "@qwik.dev/core";
import { Link } from "@qwik.dev/router";
import { loadMetaFromIdb, saveMetaToIdb } from "../../utils/idb";
import {
  COVER_LOOKUP_SETTING_KEY,
  FLOW_SETTING_EVENT,
  FLOW_SETTING_KEY,
  IN_FLOW_SETTING_EVENT,
