        <button
          key={setting}
          type="button"
          role="switch"
          aria-checked={state[setting]}
          class="review-controls__switch focus-ring"
          disabled={
            !state.ready ||
            state.saving ||
            (setting !== "enabled" && !state.enabled)
          }
          title={
            setting !== "enabled" && !state.enabled
              ? "Turn on automatic review first."
              : TITLES[setting]
          }
          onClick$={() => toggle(setting)}
