          <span class="review-controls__label">{LABELS[setting]}</span>
          <span class="review-controls__value" aria-hidden="true">
            {state[setting] ? "On" : "Off"}
          </span>
          <span class="review-controls__track" aria-hidden="true">
            <span />
          </span>
        </button>
