            { "is-in-margin": !!suggestion.margin },
          ]}
          data-margin-item={suggestion.margin ?? undefined}
          role="dialog"
          aria-label={`Proposed edit from ${suggestion.author}`}
          style={{
            left: `${suggestion.x}px`,
