            bottom:
              suggestion.bottom != null ? `${suggestion.bottom}px` : "auto",
            "max-height": `${suggestion.maxH}px`,
            width: suggestion.width ? `${suggestion.width}px` : undefined,
            "--comment-color": suggestion.color,
          }}
          onClick$={(event) => event.stopPropagation()}
        >
