        {store.notice && (
          <p class="mb-3 text-xs text-[var(--color-ink-muted)]" role="status">
            {store.notice}
          </p>
        )}
        {store.choices.length > 0 && (
          <details class="mb-4 text-xs text-[var(--color-ink-muted)]">
            <summary class="cursor-pointer">
