            <p class="sr-only">Checking grammar</p>
          </div>
        )}

        {store.status === "error" && (
          <div class="space-y-3" role="alert">
            <p class="text-xs leading-5 text-[var(--color-accent-red)]">
              {store.error}
            </p>
            <button type="button" class="btn-paper text-xs" onClick$={scan}>
              Try grammar check again
