          </div>
        )}

        {store.status === "ready" && store.unsupportedLanguage && (
          <div class="py-8 text-center" role="status">
            <p
              class="text-lg text-[var(--color-ink)]"
              style={{ fontFamily: "var(--font-display)" }}
            >
