/** A persona note anchored beside the passage it discusses. */
export interface NotePopover {
  id: string;
  author: string;
  color: string;
  label: string;
  note: string;
  x: number;
  top: number | null;
  bottom: number | null;
  maxH: number;
  placement: "above" | "below";
  quote?: string;
  briefTitle?: string;
  /** Further passages and facts behind the note, mirrored from the panel. */
