  dismissed: boolean;
  pinned: boolean;
  thread: PersonaReply[];
  replying: boolean;
  streamingReply: string;
  error: string | null;
  /** Flow item whose margin slot this card has unfolded into, if any. */
  margin?: string | null;
  /** Width of that slot; the card's own width otherwise. */
  width?: number;
}

/** A persona's proposed rewrite, presented for an explicit accept/strike decision. */
export interface SuggestionPopover {
  id: string;
  versionId: string;
  author: string;
  color: string;
  original: string;
  replacement: string;
  rationale: string;
  x: number;
  top: number | null;
  bottom: number | null;
  maxH: number;
  busy: boolean;
  /** Flow item whose margin slot this card has unfolded into, if any. */
  margin?: string | null;
  /** Width of that slot; the card's own width otherwise. */
  width?: number;
}

/** A note collected live from the document, in reading order and numbered per kind. */
export interface EditorNote {
  kind: NoteKind;
  number: number;
  text: string;
  pos: number;
}

/** A writer-authored inline comment and its reply thread. */
export interface UserCommentPopover {
  mode: "compose" | "thread";
  visible: boolean;
  id: string;
  author: string;
  text: string;
  quote: string;
  createdAt: number;
  x: number;
  top: number | null;
  bottom: number | null;
  maxH: number;
  from: number | null;
  to: number | null;
  resolved: boolean;
  replies: UserCommentReply[];
  draft: string;
  /** Flow item whose margin slot this card has unfolded into, if any. */
  margin?: string | null;
  /** Width of that slot; the card's own width otherwise. */
  width?: number;
}

/** The exact Tiptap selection owned by the manuscript action card. */
export interface SelectionActionState {
  from: number;
  to: number;
  text: string;
  /** Fixed viewport coordinates; the component centers itself on x. */
  x: number;
  y: number;
  placement: "above" | "below";
  error: string | null;
}

/**
 * Shared reactive state for the editor shell and its panels.
 *
 * Tiptap and persistence remain owned by `twyne-editor.tsx`; extracted panels
 * only read this state and send typed intents back to that orchestrator.
 */
export interface EditorStore {
  editor: Editor | null;
  meta: DocumentMeta;
  isDragOver: boolean;
  isAnalysisRunning: boolean;
  active: Record<string, boolean>;
  showImageInput: boolean;
  imageUrl: string;
  imageUploadAdapter: NoSerialize<ImageUploadAdapter> | null;
  selectedImage: ImageNodeAttributes | null;
  imageUploadError: string | null;
  showMermaidInput: boolean;
  /** Ranges being edited for the active code block; null when closed. */
  codeLinesInput: string | null;
  mermaidSource: string;
  noteInputKind: "endnote" | "footnote" | null;
  noteText: string;
  notes: EditorNote[];
  hasSelection: boolean;
  selectionAction: SelectionActionState | null;
  notePopover: NotePopover | null;
  suggestionPopover: SuggestionPopover | null;
  stampVisible: boolean;
  lastSavedAt: number | null;
  userCommentPopover: UserCommentPopover | null;
  canUndo: boolean;
  canRedo: boolean;
  activeFolioId: string;
  layout: LayoutSettings;
  /** Piece type of the active folio; selects the role set and Typst styles. */
  kit: KitId;
  headerText: string;
  footerText: string;
  showLayout: boolean;
  layoutPanelMaxH: number;
  exportingPdf: boolean;
  includePersonaCommentsInExport: boolean;
  showFindReplace: boolean;
  showGrammar: boolean;
  showShortcutDialog: boolean;
  showOutline: boolean;
  outline: DocumentOutlineModel;
  showTableInsertion: boolean;
  tableToolbar: TableToolbarSnapshot;
  cellFormat: SelectedCellFormat;
  slashOpen: boolean;
  slashQuery: string;
  slashLeft: number;
  slashTop: number;
  zenMode: boolean;
  /** Presentation only; hiding tools never unmounts the manuscript. */
  compositorOpen?: boolean;
  openPicker: "highlight" | "textColor" | "type" | "spacing" | null;
  currentColor: string | null;
  currentHighlight: string | null;
  currentFontFamily: string | null;
  currentFontSize: string | null;
  currentLineHeight: string | null;
  currentSpaceBefore: number | null;
  currentSpaceAfter: number | null;
  currentKeepWithNext: boolean;
  pageCount: number;
  paginationActive: boolean;
  /** A recoverable source draft temporarily owns manuscript editing. */
  typstSourcePending?: boolean;
  typstView?: "write" | "source" | "proof";
  toolbarTab: CompositorTab;
}

/** The serializable slice that rendered panels may read and update. */
export type EditorPanelState = Omit<
  EditorStore,
  "editor" | "imageUploadAdapter"
>;

export interface TwyneEditorProps {
  editorSignal?: Signal<NoSerialize<Editor> | undefined>;
  initialContent?: string;
  /** The folio this draft belongs to. Used to scope user comments. */
  activeFolioId?: string;
  /** The full active folio — carries layout, header, and footer. */
  activeFolio?: Folio | null;
  /** The current project brief, used to derive running-header metadata. */
  brief?: import("../../types").ProjectBrief | null;
  /** When set, the editor joins a multiplayer session. */
  sharedLixId?: string;
  /** Commenters can inspect and discuss a shared folio without editing it. */
  readOnly?: boolean;
  /** Route-owned switch between Cast, Rubric, Marginalia, and Apparatus. */
  onEditorialContext$?: PropFunction<(context: PanelId) => void>;
  /** A real manuscript interaction dismisses route-owned editorial furniture. */
  onManuscriptFocus$?: PropFunction<() => void>;
}

