        )}

        {composing ? (
          <div class="manuscript-comment-card__composer">
            <textarea
              autoFocus
              value={comment.draft}
              data-thread-draft-kind="comment"
              data-thread-draft-id={comment.id}
              onKeyDown$={(event) => {
