/**
 * The evidence an editor gathered for one note, reduced to what a margin card
 * can show: the other passages the note draws on, and the continuity facts
 * the editor read out of the draft.
 *
 * Generation returns every passage the research tools resolved and the raw
 * typed readings. Neither is stored as is: passages are deduplicated against
 * the card's own anchor and capped, and readings become plain facts — a value
 * or a closest reading, with the verbatim passages it came from. Probabilities
 * are not kept; the card never shows them.
 */
import type { PersonaExtractionReading } from "./persona-research";
import { extractQuotations } from "./quote-grounding";

export interface NoteFact {
  /** Field id the editor chose, e.g. `first_meeting_year`. */
  id: string;
  /** The id as words. */
  label: string;
  /** The reading, formatted for a line of type. */
  value: string;
  /** True when the draft only came close: a guess, not a stated fact. */
  near?: boolean;
  /** Verbatim passages the reading came from, in draft order. */
  passages: string[];
}

export interface NoteEvidence {
  /** Linked passages beyond the card's own anchor. */
  passages: string[];
  facts: NoteFact[];
}

/** One card, not a dossier: the anchor plus at most three more. */
export const MAX_EXTRA_PASSAGES = 3;
export const MAX_FACTS = 6;
const MAX_PASSAGE_CHARS = 600;

function fold(text: string): string {
  return text
    .replace(/[“”„«»]/g, '"')
    .replace(/[‘’‚]/g, "'")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function clip(text: string): string {
  const t = text.trim();
  return t.length > MAX_PASSAGE_CHARS ? t.slice(0, MAX_PASSAGE_CHARS) : t;
}

/**
 * Passages other than the primary anchor, in the order research found them,
 * without repeats or passages contained in one already kept.
 */
export function normaliseNoteAnchors(
  primary: string | undefined,
  anchors: readonly unknown[] | undefined,
): string[] {
  const kept: string[] = [];
  const seen: string[] = primary?.trim() ? [fold(primary)] : [];
  for (const raw of anchors ?? []) {
    if (typeof raw !== "string") continue;
    const passage = clip(raw);
    const key = fold(passage);
    if (key.length < 8) continue;
    if (seen.some((s) => s.includes(key) || key.includes(s))) continue;
    seen.push(key);
    kept.push(passage);
    if (kept.length >= MAX_EXTRA_PASSAGES) break;
  }
  return kept;
}

/** `first_meeting_year` → "first meeting year". */
export function factLabel(id: string): string {
  return id
    .replace(/([a-z])([A-Z])/g, "$1 $2")
    .replace(/[_-]+/g, " ")
    .trim()
    .toLowerCase();
}

function formatScalar(value: unknown, unit?: string): string | null {
  if (value == null) return null;
  if (typeof value === "number") {
    if (!Number.isFinite(value)) return null;
    const n = Number.isInteger(value)
      ? String(value)
      : String(Math.round(value * 100) / 100);
    return unit ? `${n} ${unit}` : n;
  }
  if (typeof value === "boolean") return value ? "yes" : "no";
  if (typeof value === "string") return value.trim() || null;
  if (Array.isArray(value)) {
    const items = value
      .map((v) => formatScalar(v))
      .filter((v): v is string => !!v);
    return items.length ? items.join("; ") : null;
  }
  return null;
}

/** A value, or the 10–90 interval when the field is an estimate. */
function formatAnswer(
  answer: PersonaExtractionReading["answers"][string],
  unit: string | undefined,
  raw: unknown,
): string | null {
  const lo = formatScalar(answer.p10);
  const hi = formatScalar(answer.p90);
  if (
    (answer.type === "estimate" || answer.type === "forecast") &&
    lo &&
    hi &&
    lo !== hi
  ) {
    return unit ? `${lo}–${hi} ${unit}` : `${lo}–${hi}`;
  }
  return formatScalar(raw, unit);
}

/** Typed readings as card facts. Answers with neither value nor guess are dropped. */
export function factsFromReadings(
  readings: readonly PersonaExtractionReading[] | undefined,
): NoteFact[] {
  const out: NoteFact[] = [];
  const ids = new Set<string>();
  for (const reading of readings ?? []) {
    for (const [id, answer] of Object.entries(reading?.answers ?? {})) {
      if (!answer || ids.has(id)) continue;
      const unit = answer.unit ?? reading.fields?.[id]?.unit;
      const exact = answer.value != null;
      const value = formatAnswer(
        answer,
        unit,
        exact ? answer.value : answer.guess,
      );
      if (!value) continue;
      const passages = [answer.source, ...(answer.passages ?? [])]
        .map((p) => p?.passage)
        .filter((p): p is string => typeof p === "string" && !!p.trim())
        .map(clip)
        .filter((p, i, all) => all.indexOf(p) === i)
        .slice(0, 2);
      ids.add(id);
      out.push({
        id,
        label: factLabel(id),
        value: value.length > 160 ? value.slice(0, 159) + "…" : value,
        ...(exact ? {} : { near: true }),
        passages,
      });
      if (out.length >= MAX_FACTS) return out;
    }
  }
  return out;
}

/** Anything persisted or synced, back into a shape the card can trust. */
export function normaliseNoteFacts(input: unknown): NoteFact[] {
  if (!Array.isArray(input)) return [];
  const out: NoteFact[] = [];
  for (const f of input) {
    if (!f || typeof f !== "object") continue;
    const r = f as Record<string, unknown>;
    if (typeof r.id !== "string" || typeof r.value !== "string") continue;
    out.push({
      id: r.id,
      label: typeof r.label === "string" ? r.label : factLabel(r.id),
      value: r.value,
      ...(r.near === true ? { near: true } : {}),
      passages: Array.isArray(r.passages)
        ? r.passages
            .filter((p): p is string => typeof p === "string")
            .slice(0, 2)
        : [],
    });
    if (out.length >= MAX_FACTS) break;
  }
  return out;
}

/**
 * What the card shows beyond its anchor and body. A passage the note already
 * quotes is linked inline, so it is not listed again underneath.
 */
export function noteEvidence(note: {
  feedback: string;
  anchor?: string;
  anchors?: readonly unknown[];
  facts?: unknown;
}): NoteEvidence {
  const quoted = extractQuotations(note.feedback).map((q) => fold(q.quote));
  const passages = normaliseNoteAnchors(note.anchor, note.anchors).filter(
    (p) => {
      const key = fold(p);
      return !quoted.some(
        (q) => q.length >= 8 && (key.includes(q) || q.includes(key)),
      );
    },
  );
  // A fact the writer cannot check against the draft does not support the
  // note; only readings with a source passage are shown.
  const facts = normaliseNoteFacts(note.facts).filter(
    (f) => f.passages.length > 0,
  );
  return { passages, facts };
}

/** Fields to store on a note at the moment it is filed. */
export function evidenceFields(response: {
  anchor?: string;
  anchors?: readonly unknown[];
  extractions?: readonly PersonaExtractionReading[];
}): { anchors?: string[]; facts?: NoteFact[] } {
  const anchors = normaliseNoteAnchors(response.anchor, response.anchors);
  const facts = factsFromReadings(response.extractions);
  return {
    ...(anchors.length ? { anchors } : {}),
    ...(facts.length ? { facts } : {}),
  };
}
/**
 * Writer-authored inline comments — local persistence. The CommentMark
 * in the manuscript holds the id; the body, replies, and resolve state
 * live in Lix at `/user-comments.json`. The same shape gets pushed to
 * Convex via `convex-sync.ts:pushLocalSnapshot`, so the cross-device
 * sync is automatic.
 *
 * The shape is deliberately flat — comments and replies are denormalised
 * so the editor can render without a join.
 *
 * This is the single source of truth for "the room's comments on the
 * manuscript" — the inline CommentMark popover and the right-rail
 * Marginalia panel both read and write here. The legacy `/comments.json`
 * shape is migrated on first load.
 */

import { readFileAsJson, writeFileAsJson } from "./lix";

export type UserCommentAuthor = "user" | "persona";

export interface UserCommentReply {
  id: string;
  author: string;
  /** user = the writer; persona = an editor answering the thread. */
  authorKind: UserCommentAuthor;
  /** Set when authorKind === "persona". */
  personaId?: string;
  /** Color swatch to render the reply in (mirrors the persona's accent). */
  color?: string;
  text: string;
  createdAt: number;
}

export interface UserComment {
  id: string;
  folioId: string;
  text: string;
  author: string;
  /** The passage the comment was pinned to (for scroll-to + display). */
  anchor?: string;
  resolved: boolean;
  createdAt: number;
  updatedAt: number;
  replies: UserCommentReply[];
  /**
   * Key into the local `voice-notes` IndexedDB store when this note was
   * spoken. The comment's `text` is the transcript; this is the recording it
   * came from, which carries the hesitation and emphasis the transcript
   * drops. Local-only by design — audio does not sync.
   */
  audioId?: string;
  audioDurationMs?: number;
  /** Which provider produced the transcript, for the provider tag. */
  transcriptProvider?: string;
}

const COMMENTS_PATH = "/user-comments.json";
const LEGACY_COMMENTS_PATH = "/comments.json";

export async function loadUserComments(): Promise<UserComment[]> {
  if (typeof window === "undefined") return [];
  try {
    const data = await readFileAsJson<UserComment[]>(COMMENTS_PATH);
    if (data && data.length > 0) return data;
  } catch {
    // fall through to migration
  }
  // One-time migration from the legacy `/comments.json` panel model into
  // the unified UserComment store. New comments are anchored by selection;
  // legacy ones had no anchor, so we keep `selectedText` as the anchor.
  try {
    const legacy = await readFileAsJson<LegacyComment[]>(LEGACY_COMMENTS_PATH);
    if (Array.isArray(legacy) && legacy.length > 0) {
      const migrated: UserComment[] = legacy.map((c) => ({
        id: c.id,
        folioId: "", // legacy comments had no folio scope
        text: c.text,
        author: c.author,
        anchor: c.selectedText || undefined,
        resolved: c.resolved,
        createdAt: c.timestamp,
        updatedAt: c.timestamp,
        replies: (c.replies ?? []).map((r) => ({
          id: r.id,
          author: r.author,
          authorKind: "user",
          text: r.text,
          createdAt: r.timestamp,
        })),
      }));
      await writeFileAsJson(COMMENTS_PATH, migrated);
      // Wipe the legacy path so we don't re-migrate next time.
      try {
        await writeFileAsJson(LEGACY_COMMENTS_PATH, []);
      } catch {
        // best-effort
      }
      return migrated;
    }
  } catch {
    // no legacy file
  }
  return [];
}

export async function saveUserComments(comments: UserComment[]): Promise<void> {
  if (typeof window === "undefined") return;
  try {
    await writeFileAsJson(COMMENTS_PATH, comments);
  } catch {
    // lix unavailable
  }
}

/**
 * Drop every writer-authored thread from the Lix store. Used
 * by "File a new piece" — without this, the threads would
 * orphan against the (now empty) folios and turn into ghost
 * notes the next time the writer opens the editor. Returns
 * the number of threads cleared so the caller can show a
 * confirmation.
 */
export async function clearUserComments(): Promise<number> {
  if (typeof window === "undefined") return 0;
  let count = 0;
  try {
    const all = await loadUserComments();
    count = all.length;
    await writeFileAsJson(COMMENTS_PATH, []);
  } catch {
    // best-effort
  }
  return count;
}

export async function upsertUserComment(
  c: UserComment,
): Promise<UserComment[]> {
  const all = await loadUserComments();
  const idx = all.findIndex((x) => x.id === c.id);
  if (idx >= 0) {
    // Merge: keep any replies that landed before the parent body
    // (e.g. a reply sent in the same race window where the popover
    // opened before persistNewComment finished). The caller controls
    // the body, anchor, folioId, and resolve state; the reply thread
    // is owned by appendUserCommentReply, so we never clobber it.
    all[idx] = {
      ...all[idx],
      ...c,
      replies: c.replies.length > 0 ? c.replies : all[idx].replies,
    };
  } else {
    all.push(c);
  }
  await saveUserComments(all);
  return all;
}

export async function appendUserCommentReply(
  commentId: string,
  reply: UserCommentReply,
  /** Optional late-result guard, evaluated against storage after its async read. */
  canAppend?: (comment: UserComment | undefined) => boolean,
): Promise<UserComment[]> {
  const all = await loadUserComments();
  const idx = all.findIndex((x) => x.id === commentId);
  if (canAppend && !canAppend(idx < 0 ? undefined : all[idx])) return all;
  const now = Date.now();
  if (idx < 0) {
    // The parent comment hasn't been persisted yet — usually because the
    // editor opened the popover the same instant it set the mark, and the
    // upsert and the reply are racing. Rather than silently drop the
    // writer's reply, file a placeholder parent that owns the reply. The
    // subsequent upsert will merge into it (same id, body filled in).
    all.push({
      id: commentId,
      folioId: "",
      text: "",
      author: reply.authorKind === "persona" ? reply.author : "You",
      resolved: false,
      createdAt: reply.createdAt,
      updatedAt: now,
      replies: [reply],
    });
    await saveUserComments(all);
    return all;
  }
  all[idx] = {
    ...all[idx],
    replies: [...all[idx].replies, reply],
    updatedAt: now,
  };
  await saveUserComments(all);
  return all;
}

export async function toggleUserCommentResolved(
  commentId: string,
): Promise<UserComment[]> {
  const all = await loadUserComments();
  const idx = all.findIndex((x) => x.id === commentId);
  if (idx < 0) return all;
  all[idx] = {
    ...all[idx],
    resolved: !all[idx].resolved,
    updatedAt: Date.now(),
  };
  await saveUserComments(all);
  return all;
}

export async function deleteUserComment(
  commentId: string,
): Promise<UserComment[]> {
  return deleteUserComments([commentId]);
}

/**
 * Remove several threads in one read/write cycle. Anchor reconciliation can
 * find more than one deleted passage at a time; writing each deletion from a
 * separate stale snapshot could otherwise resurrect a sibling thread.
 */
export async function deleteUserComments(
  commentIds: Iterable<string>,
  /** Recheck source and scope after the storage read before pruning a thread. */
  canDelete?: (comment: UserComment) => boolean,
): Promise<UserComment[]> {
  const ids = new Set(commentIds);
  if (ids.size === 0) return loadUserComments();
  const all = await loadUserComments();
  const next = all.filter(
    (comment) => !ids.has(comment.id) || (canDelete && !canDelete(comment)),
  );
  if (next.length === all.length) return all;
  await saveUserComments(next);
  return next;
}

/* ── Legacy shape, used only for the one-time migration ───────── */

interface LegacyCommentReply {
  id: string;
  text: string;
  author: string;
  timestamp: number;
}

interface LegacyComment {
  id: string;
  text: string;
  selectedText: string;
  from: number;
  to: number;
  author: string;
  timestamp: number;
  resolved: boolean;
  replies: LegacyCommentReply[];
}
