        onHighlight$={(hex) => {
          store.currentHighlight = hex;
          store.active.highlight = !!hex;
          action.value = hex ? `Highlight: ${hex}` : "Highlight cleared";
        }}
        onTextColor$={(hex) => {
          store.currentColor = hex;
          action.value = hex ? `Text colour: ${hex}` : "Default ink";
        }}
        onFontFamily$={(value) => {
          store.currentFontFamily = value;
        }}
        onFontSize$={(value) => {
