import { component$, useStore, useTask$ } from "@qwik.dev/core";
import type { Meta, StoryObj } from "storybook-framework-qwik";
import type { SuggestionPopover } from "./editor-state";
import { SuggestionPanel } from "./suggestion-panel";
import { copyFixture, ModalCardStage, proposedEdit } from "./modal-card.fixtures";

const SuggestionPreview = component$<{ suggestion: SuggestionPopover; stampVisible: boolean }>((props) => {
  const state = useStore({ suggestion: copyFixture(props.suggestion) as SuggestionPopover | null, stampVisible: props.stampVisible, status: "Local preview. Accept or strike the proposed edit." });
  useTask$(({ track }) => {
    state.suggestion = copyFixture(track(() => props.suggestion));
    state.stampVisible = track(() => props.stampVisible);
  });
  return <ModalCardStage status={state.status} onReset$={() => {
    state.suggestion = copyFixture(props.suggestion);
    state.stampVisible = props.stampVisible;
    state.status = "Preview reset";
  }}>
    <SuggestionPanel suggestion={state.suggestion} stampVisible={state.stampVisible}
      onClose$={() => { state.suggestion = null; state.status = "Proposed edit closed"; }}
      onStrike$={() => { state.suggestion = null; state.status = "Proposed edit struck. Original retained in preview."; }}
      onAccept$={() => { state.suggestion = null; state.stampVisible = true; state.status = "Proposed edit accepted in preview"; }}
    />
  </ModalCardStage>;
});

const meta = {
  title: "Editor/SuggestionPanel",
  component: SuggestionPreview,
  parameters: { layout: "fullscreen" },
  args: { suggestion: proposedEdit, stampVisible: false },
} satisfies Meta<typeof SuggestionPreview>;
