import { component$, Slot, type PropFunction } from "@qwik.dev/core";
import type { NotePopover, SuggestionPopover, UserCommentPopover } from "./editor-state";

/** Fictional manuscript and conversation fixtures, never persisted or generated. */
export const passage = "The library was the only room in the city where nobody had to buy anything to stay.";
export const fixtureTime = Date.UTC(2026, 10, 3, 14);
const position = { x: 24, top: 112, bottom: null, maxH: 640 };

export const personaNote: NotePopover = {
  ...position,
  id: "story-persona-note",
  author: "George Orwell",
  color: "#526b55",
  label: "on clarity",
  note: "The claim in **‘nobody had to buy anything’** is strong. Show us the room before you explain its public purpose. Who is sitting there, and what are they doing?",
  quote: passage,
  briefTitle: "The public room",
  placement: "below",
  draft: "",
  dismissed: false,
  pinned: true,
  thread: [],
  replying: false,
  streamingReply: "",
  error: null,
};

export const proposedEdit: SuggestionPopover = {
  ...position,
  id: "story-proposed-edit",
  versionId: "story-version",
  author: "George Orwell",
  color: "#526b55",
  original: "It could be said that the library was, in a very real sense, a place that was available to everyone.",
  replacement: passage,
  rationale: "Cut the qualifications and name the practical difference: **you can stay without spending money**.",
  busy: false,
};

export const writerComment: UserCommentPopover = {
  ...position,
  mode: "thread",
  visible: true,
  id: "story-writer-note",
  author: "You",
  text: "Return to this claim after the interview. Does **every branch** offer the same access?",
  quote: passage,
  createdAt: fixtureTime,
  from: 1,
  to: passage.length + 1,
  resolved: false,
  replies: [],
  draft: "",
};

/** Qwik props may be proxies; copy plain fixture data without structuredClone. */
export function copyFixture<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

export const ModalCardStage = component$<{
  status: string;
  onReset$: PropFunction<() => void>;
}>((props) => (
  <section style="min-height: 100dvh; padding: 1rem 1.5rem; background: var(--color-paper-soft);">
    <div class="flex items-center gap-3">
      <button class="btn-paper text-xs" onClick$={props.onReset$}>Reset preview</button>
      <p role="status" class="text-xs text-[var(--color-ink-light)]">{props.status}</p>
    </div>
    <Slot />
  </section>
));

import { component$, useStore, useTask$ } from "@qwik.dev/core";
import type { Meta, StoryObj } from "storybook-framework-qwik";
import type { UserCommentPopover } from "./editor-state";
import { UserCommentPanel } from "./user-comment-panel";
import { copyFixture, fixtureTime, ModalCardStage, writerComment } from "./modal-card.fixtures";

const WriterNotePreview = component$<{ comment: UserCommentPopover }>((props) => {
  const state = useStore({ comment: copyFixture(props.comment) as UserCommentPopover | null, status: "Local preview. Place, reply to, or resolve a margin note." });
  useTask$(({ track }) => { state.comment = copyFixture(track(() => props.comment)); });
  return <div onInput$={(event) => {
    const input = event.target as HTMLTextAreaElement;
    if (input.dataset.threadDraftKind === "comment" && state.comment) state.comment.draft = input.value;
  }}>
    <ModalCardStage status={state.status} onReset$={() => {
      state.comment = copyFixture(props.comment);
      state.status = "Preview reset";
    }}>
      <UserCommentPanel comment={state.comment}
        onClose$={() => { state.comment = null; state.status = "Margin note closed"; }}
        onDiscard$={() => { state.comment = null; state.status = "Draft discarded"; }}
        onCreate$={() => {
          if (!state.comment?.draft.trim()) return;
          state.comment.text = state.comment.draft.trim();
          state.comment.draft = "";
          state.comment.mode = "thread";
          state.comment.createdAt = Date.now();
          state.status = "Margin note placed locally";
        }}
        onSubmit$={() => {
          if (!state.comment?.draft.trim()) return;
          state.comment.replies.push({ id: `reply-${state.comment.replies.length}`, author: "You", authorKind: "user", text: state.comment.draft.trim(), createdAt: Date.now() });
          state.comment.draft = "";
          state.status = "Writer reply added locally";
        }}
        onToggleResolved$={() => {
          if (!state.comment) return;
          state.comment.resolved = !state.comment.resolved;
          state.status = state.comment.resolved ? "Margin note resolved" : "Margin note reopened";
        }}
        onDelete$={() => { state.comment = null; state.status = "Margin note erased"; }}
      />
    </ModalCardStage>
  </div>;
});

