import { PersonaNotePanel } from "./persona-note-panel";
import { copyFixture, fixtureTime, ModalCardStage, personaNote } from "./modal-card.fixtures";

const PersonaNotePreview = component$<{ note: NotePopover }>((props) => {
  const state = useStore({ note: copyFixture(props.note) as NotePopover | null, status: "Local preview. Replies stay in this story." });
  useTask$(({ track }) => {
    state.note = copyFixture(track(() => props.note));
  });
  return (
    <div onInput$={(event) => {
      const input = event.target as HTMLTextAreaElement;
      if (input.dataset.threadDraftKind === "note" && state.note) state.note.draft = input.value;
    }}>
      <ModalCardStage status={state.status} onReset$={() => {
        state.note = copyFixture(props.note);
        state.status = "Preview reset";
      }}>
        <PersonaNotePanel
          note={state.note}
          onPin$={() => { if (state.note) state.note.pinned = true; }}
          onClose$={() => { state.note = null; state.status = "Note closed"; }}
          onStrike$={() => { state.note = null; state.status = "Note struck"; }}
          onReply$={(noteId, text) => {
            if (!state.note || !text.trim()) return;
            state.note.thread.push({ id: `preview-${state.note.thread.length}`, noteId, author: "You", authorKind: "user", text: text.trim(), timestamp: Date.now() });
            state.note.draft = "";
            state.status = "Writer reply added locally. No editor response is generated.";
          }}
        />
      </ModalCardStage>
    </div>
  );
});

