import { chromium, expect } from '@playwright/test';
const browser=await chromium.launch();
try{
 const page=await browser.newPage({viewport:{width:1200,height:900}});
 const errors=[]; const external=[];
 page.on('pageerror',e=>errors.push(e.message));
 page.on('request',r=>{if(!r.url().startsWith('http://127.0.0.1:6010') && !r.url().startsWith('data:'))external.push(r.url())});
 await page.goto('http://127.0.0.1:6010/iframe.html?id=rubric-quickmark--estimated-grade&viewMode=story',{waitUntil:'domcontentloaded'});
 await page.getByRole('button',{name:'Grade again'}).waitFor({timeout:60000});
 await page.getByText('How this was scored',{exact:true}).click();
 await expect(page.getByText(/Treat it as an estimate/)).toBeVisible();
 await page.screenshot({path:'/tmp/twyne-quick-mark.png'});
 await page.getByRole('button',{name:'Grade again'}).click();
 await expect(page.getByText('Preview only. No grading request was sent.',{exact:true})).toBeVisible();
 await page.getByRole('button',{name:/Change what's graded/}).click();
 await page.getByRole('textbox',{name:'New criterion name'}).fill('Local detail');
 await page.getByRole('button',{name:'+ Add',exact:true}).click();
 await expect(page.getByText('Local detail',{exact:true})).toBeVisible();
 await page.getByRole('button',{name:/Editors/}).click();
 await page.getByRole('button',{name:'Ask them now'}).click();
 console.log('PASS rubric explanation, local criteria, safe grade and editor actions',JSON.stringify({errors,external}));
 await page.goto('http://127.0.0.1:6010/iframe.html?id=editor-documentsections--navigate-and-reorder&viewMode=story',{waitUntil:'domcontentloaded'});
 await page.locator('.ProseMirror h2').first().waitFor({timeout:60000});
 await page.getByRole('button',{name:'Go to Who gets to stay'}).click();
 await page.getByRole('button',{name:'Move last section up'}).click();
 await expect(page.locator('.ProseMirror h2').first()).toHaveText('What cities should fund');
 await page.screenshot({path:'/tmp/twyne-sections.png'});
 console.log('PASS outline navigation and section reorder');
 await page.goto('http://127.0.0.1:6010/iframe.html?id=editor-pageruler--interactive&viewMode=story',{waitUntil:'domcontentloaded'});
 await page.getByRole('slider').first().waitFor({timeout:60000});
 const slider=page.getByRole('slider').first();
 const before=await slider.getAttribute('aria-valuenow');
 await slider.focus(); await page.keyboard.press('ArrowRight');
 await expect(slider).not.toHaveAttribute('aria-valuenow',before);
 await page.screenshot({path:'/tmp/twyne-ruler.png'});
 console.log('PASS ruler keyboard interaction',errors);
 if(errors.length)process.exitCode=1;
}finally{await browser.close();}
