    const frame = requestAnimationFrame(() => {
      if (mode === "finding") {
        closePopover = renderQuickReviewFinding(editor, 0, editor.state.doc.firstChild!.nodeSize, { label, tentative }, () => {
          closePopover();
          clearQuickReviewFinding(editor);
          publish("No clear issue in this passage");
