        if (open) mount.value?.querySelector<HTMLButtonElement>(".twyne-quick-review-marker")?.click();
      } else if (mode in notices) {
        const notice = notices[mode as keyof typeof notices];
        publish(notice.label, "", notice.reason);
      } else {
        publish({ waiting: "Waiting for a pause…", checking: "Checking this passage…", clear: "No clear issue in this passage" }[mode as "waiting" | "checking" | "clear"]);
      }
    });
    dispose = () => { cancelAnimationFrame(frame); closePopover(); editor.destroy(); };
  });

