 await p.getByRole('button',{name:'Check evidence',exact:true}).click();
 await expect(p.locator('.live-review-status__detail')).toBeVisible();
 await marker.click();
 await p.getByRole('dialog',{name:'Passage feedback'}).waitFor();
 await p.screenshot({path:'/tmp/twyne-inline-quick-review.png'});
 await p.getByRole('button',{name:'Dismiss',exact:true}).click();
 await expect(p.getByRole('dialog')).toHaveCount(0);
 await expect(marker).toHaveCount(0);
 await p.getByRole('button',{name:'Reset preview'}).click();
 await marker.waitFor();
 await p.getByRole('textbox',{name:'Quick-review manuscript'}).press('ControlOrMeta+End');
 await p.keyboard.type(' A revision.');
 await expect(marker).toHaveCount(0);
 console.log('PASS expand status, open/dismiss marker, reset, edit removes decoration');
 const index=await(await fetch('http://127.0.0.1:6010/index.json')).json();
 const entries=Object.values(index.entries).filter(e=>e.id.startsWith('editor-inlinequickreview--'));
 for(const e of entries){
  await p.setViewportSize({width:e.id.endsWith('--mobile-feedback')?390:1100,height:900});
  await p.goto(`http://127.0.0.1:6010/iframe.html?id=${e.id}&viewMode=story`,{waitUntil:'domcontentloaded'});
  await p.locator('.ProseMirror').waitFor({timeout:60000});
  if(/--(signed-out|model-not-configured|review-unavailable)$/.test(e.id)){
   await p.getByRole('button',{name:'Dismiss review notice'}).waitFor();
   await p.getByRole('button',{name:'Dismiss review notice'}).click();
   await expect(p.locator('.live-review-status--notice')).toHaveCount(0);
   await p.getByRole('button',{name:'Reset preview'}).click();
   await p.getByRole('button',{name:'Dismiss review notice'}).waitFor();
  }
  if(/--(passage-feedback-open|mobile-feedback)$/.test(e.id)){
   await p.getByRole('dialog',{name:'Passage feedback'}).waitFor();
   if(e.id.endsWith('--mobile-feedback')){
    await p.screenshot({path:'/tmp/twyne-inline-quick-review-mobile.png'});
    const r=await p.getByRole('dialog').boundingBox();
    if(!r||r.x<0||r.x+r.width>391)throw Error('Mobile popover overflow');
   }
  }
  await expect(p.locator('body')).not.toContainText('Error: Code(');
  console.log('PASS',e.id);
 }
 console.log(JSON.stringify({stories:entries.length,errors,external}));
 if(errors.length||external.length)process.exitCode=1;
}finally{await b.close();}
